class Solution {
public:
    long long maxSumTrionic(vector<int>& nums) {
        const long long NEG=LLONG_MIN/4;
        long long up=NEG,down=NEG,finalUp=NEG,answer=NEG;
        for(int i=1;i<(int)nums.size();++i) {
            long long a=nums[i-1],b=nums[i];
            long long nu=NEG,nd=NEG,nf=NEG;
            if(b>a) {
                nu=max(a+b,up+b);
                if(finalUp!=NEG) nf=max(nf,finalUp+b);
                if(down!=NEG) nf=max(nf,down+b);
            } else if(b<a) {
                if(up!=NEG) nd=max(nd,up+b);
                if(down!=NEG) nd=max(nd,down+b);
            }
            up=nu;down=nd;finalUp=nf;
            answer=max(answer,finalUp);
        }
        return answer;
    }
};
